/* ──────────────────────────────────────────────────────────────────────────
   PAGE 22 — MY WORKSTATION (Operator view, rebuilt model)
   The operator's personal view: one tab per assigned workstation, each with
   its own queue and independent job timers. Operators Start / Pause / Resume /
   Close jobs; every action is timestamped server-side. Timers tick locally and
   re-sync from server figures on each poll.
   ────────────────────────────────────────────────────────────────────────── */

const MONO = "'IBM Plex Mono', monospace";
const ARCHIVO = "'Archivo', sans-serif";
const SANS = "'IBM Plex Sans', sans-serif";

const T_PRIMARY = 'var(--text-primary, #15366a)';
const T_SECONDARY = 'var(--text-secondary, #5d7188)';
const T_MUTED = 'var(--text-muted, #9bb4d4)';

/* Tempering steps require actual temperature + soak time on close. */
const TEMPERING_STEPS = [9, 10, 14, 23];
/* §23 — contextual QC measurement steps.
   Width (mm):     Bunch Grinding (4), Angle Grinding (22)
   Thickness (mm): OP10 Rough Mill (5), Surface Grind 1 (12), Surface Grind 2 (20)
   Final Inspection (26): width + thickness + HRC + Design/Cycle/HT confirmations */
const WIDTH_STEPS = [4, 22];
const THICKNESS_STEPS = [5, 12, 20];
const SURFACE_GRIND_STEPS = THICKNESS_STEPS; // legacy alias
const FINAL_STEP = 26;
const TOTAL_STEPS = 27;

/* Finished-good tolerances for the live pass/concession/reject hint (§19).
   Backend re-evaluates authoritatively against Master Lists on close. */
const TOL = { width: { min: 180, max: 182 }, thickness: { min: 16, max: 16.5 } };
function toleranceHint(dimension, value) {
  const v = Number(value);
  const t = TOL[dimension];
  if (!t || !Number.isFinite(v) || value === '' || value == null) return null;
  if (v < t.min) return { status: 'concession', label: `Below ${t.min}mm — concession (Manager/Admin approval)` };
  if (v > t.max) return { status: 'reject', label: `Above ${t.max}mm — reject, return for grinding` };
  return { status: 'pass', label: `In range (${t.min}–${t.max}mm)` };
}

/* ── helpers ─────────────────────────────────────────────────────────────── */

function fmtHMS(totalSeconds) {
  const s = Math.max(0, Math.floor(totalSeconds || 0));
  const hh = String(Math.floor(s / 3600)).padStart(2, '0');
  const mm = String(Math.floor((s % 3600) / 60)).padStart(2, '0');
  const ss = String(s % 60).padStart(2, '0');
  return `${hh}:${mm}:${ss}`;
}

/* Seconds elapsed from an ISO timestamp until `nowMs`. Tolerant of nulls. */
function elapsedFrom(iso, nowMs) {
  if (!iso) return 0;
  const t = new Date(iso).getTime();
  if (Number.isNaN(t)) return 0;
  return Math.max(0, (nowMs - t) / 1000);
}

/* Pull the first non-null value across a set of candidate keys. */
function pick(obj, ...keys) {
  if (!obj) return undefined;
  for (const k of keys) if (obj[k] != null) return obj[k];
  return undefined;
}

function jobId(job) {
  return pick(job, 'id', 'job_id', 'jobId', '_id');
}

function jobStatus(job) {
  return String(pick(job, 'status', 'state', 'job_status') || 'queued').toLowerCase();
}

function jobStep(job) {
  return pick(job, 'step', 'step_no', 'current_step', 'stepNumber');
}

/* Net work time the server has accumulated, in seconds (excludes pauses). */
function serverNetSeconds(job) {
  const v = pick(job, 'net_work_seconds', 'net_seconds', 'active_seconds', 'net_work_time_seconds');
  return Number(v) || 0;
}

/* ── live timer hook: one ticking clock for the whole page ────────────────── */

function useNow(active) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!active) return undefined;
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, [active]);
  return now;
}

/* Compute the live timer figures for a job, re-syncing from server numbers.
   - net   : net work time so far (server net + seconds since last resume if running)
   - active: time since last resume/start (running only)
   - paused: pause duration so far (paused only) */
function computeTimers(job, nowMs) {
  const status = jobStatus(job);
  const base = serverNetSeconds(job);
  if (status === 'in_progress' || status === 'running' || status === 'active') {
    const since = elapsedFrom(
      pick(job, 'resumed_at', 'last_resume_at', 'started_at', 'start_at', 'start_time'),
      nowMs
    );
    return { net: base + since, active: since, paused: 0, status };
  }
  if (status === 'paused') {
    const pausedFor = elapsedFrom(pick(job, 'paused_at', 'last_pause_at', 'pause_time'), nowMs);
    return { net: base, active: 0, paused: pausedFor, status };
  }
  return { net: base, active: 0, paused: 0, status };
}

/* ── small presentational atoms ──────────────────────────────────────────── */

function Label({ children, style }) {
  return (
    <div style={{ fontFamily: MONO, fontSize: 9.5, letterSpacing: '0.12em', textTransform: 'uppercase', color: T_MUTED, ...style }}>
      {children}
    </div>
  );
}

function Mono({ children, style }) {
  return <span style={{ fontFamily: MONO, ...style }}>{children}</span>;
}

function dotColor(status) {
  if (status === 'in_progress' || status === 'running' || status === 'active') return '#22a06b';
  if (status === 'paused') return '#d97a2b';
  if (status === 'ready') return '#3b82f6';
  return '#9aa0a6';
}

/* 27-node step progress track. Current step pulses. */
function StepTrack({ step }) {
  const current = Number(step) || 0;
  return (
    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
      {Array.from({ length: TOTAL_STEPS }, (_, i) => {
        const n = i + 1;
        const done = n < current;
        const isCurrent = n === current;
        return (
          <span
            key={n}
            title={`Step ${n}`}
            style={{
              width: 18,
              height: 18,
              borderRadius: 5,
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontFamily: MONO,
              fontSize: 9,
              fontWeight: 700,
              color: isCurrent ? '#fff' : done ? '#1c7a52' : T_MUTED,
              background: isCurrent ? 'var(--status-success, #22a06b)' : done ? 'var(--accent-green, #d4eecb)' : 'var(--bg-muted, #f4f7f2)',
              border: '1px solid ' + (isCurrent ? 'var(--status-success, #22a06b)' : 'var(--border-card, #e3ebde)'),
              animation: isCurrent ? 'cp-pulse 1.6s ease-in-out infinite' : 'none',
            }}
          >
            {n}
          </span>
        );
      })}
    </div>
  );
}

/* ── modal shell ─────────────────────────────────────────────────────────── */

function Modal({ title, onClose, children, width = 520 }) {
  return (
    <div
      onMouseDown={onClose}
      style={{ position: 'fixed', inset: 0, background: 'rgba(10,29,58,0.42)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 80, padding: 20 }}
    >
      <div
        onMouseDown={(e) => e.stopPropagation()}
        className="card cp-fade-in"
        style={{ width: '100%', maxWidth: width, maxHeight: '90vh', overflowY: 'auto', boxShadow: 'var(--shadow-modal)', padding: 0 }}
      >
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '18px 22px', borderBottom: '1px solid var(--border-card, #e3ebde)' }}>
          <div style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 16, letterSpacing: '-0.02em', color: T_PRIMARY }}>{title}</div>
          <button onClick={onClose} className="btn btn-sm" style={{ width: 32, padding: 0, justifyContent: 'center' }} aria-label="Close">
            <Icon name="close" size={16} />
          </button>
        </div>
        <div style={{ padding: '20px 22px' }}>{children}</div>
      </div>
    </div>
  );
}

function RadioRow({ name, value, current, onChange, children }) {
  const selected = current === value;
  return (
    <label
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: 10,
        padding: '11px 13px',
        borderRadius: 'var(--radius-lg, 11px)',
        border: '1.5px solid ' + (selected ? 'var(--status-blue, #3b82f6)' : 'var(--border-input, #d6e0d2)'),
        background: selected ? 'var(--bg-soft-blue, #eaf0f7)' : 'var(--bg-card, #fff)',
        cursor: 'pointer',
        marginBottom: 8,
      }}
    >
      <input type="radio" name={name} checked={selected} onChange={() => onChange(value)} style={{ width: 17, height: 17, accentColor: '#3b82f6' }} />
      <span style={{ fontFamily: SANS, fontSize: 13.5, color: T_PRIMARY }}>{children}</span>
    </label>
  );
}

/* ── Pause modal ─────────────────────────────────────────────────────────── */

function PauseModal({ job, onCancel, onConfirm, busy }) {
  const [reason, setReason] = useState(null);
  const [notes, setNotes] = useState('');
  const needNotes = reason === 'Other';
  const valid = reason && (!needNotes || notes.trim());

  return (
    <Modal title="Pause reason — required" onClose={busy ? () => {} : onCancel}>
      <div style={{ fontFamily: SANS, fontSize: 12.5, color: T_SECONDARY, marginBottom: 14 }}>
        {pick(job, 'uid', 'uid_code', 'code')} · Step {jobStep(job)} — the job stays running until you confirm a reason.
      </div>
      {PAUSE_REASONS.map((r) => (
        <RadioRow key={r} name="pause-reason" value={r} current={reason} onChange={setReason}>
          {r === 'Other' ? 'Other (enter reason below)' : r}
        </RadioRow>
      ))}
      <textarea
        className="form-input"
        placeholder={needNotes ? 'Reason (required for Other)' : 'Optional notes'}
        value={notes}
        onChange={(e) => setNotes(e.target.value)}
        rows={3}
        style={{ height: 'auto', padding: 11, resize: 'vertical', marginTop: 4 }}
      />
      <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 10, marginTop: 18 }}>
        <button className="btn" style={{ height: 48, padding: '0 22px' }} onClick={onCancel} disabled={busy}>Cancel</button>
        <button
          className="btn btn-primary"
          style={{ height: 48, padding: '0 22px' }}
          disabled={!valid || busy}
          onClick={() => onConfirm(reason, notes.trim())}
        >
          {busy ? 'Pausing…' : 'Confirm pause'}
        </button>
      </div>
    </Modal>
  );
}

/* ── Close modal ─────────────────────────────────────────────────────────── */

const QC_OPTIONS = ['No QC check for this step', 'Hardness (HRC)', 'Width (mm)', 'Straightness', 'Visual'];

/* Small tolerance-hint chip shown live under a width/thickness field. */
function ToleranceChip({ hint }) {
  if (!hint) return null;
  const c = hint.status === 'pass' ? '#22a06b' : hint.status === 'concession' ? '#d97a2b' : '#e5484d';
  return (
    <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, marginTop: 6, fontFamily: SANS, fontSize: 11.5, color: c }}>
      <span style={{ width: 8, height: 8, borderRadius: 4, background: c }} />{hint.label}
    </div>
  );
}

function YesNo({ label, value, onChange }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, padding: '7px 0' }}>
      <span style={{ fontFamily: SANS, fontSize: 13, color: T_PRIMARY }}>{label}</span>
      <div style={{ display: 'flex', gap: 6 }}>
        {['Y', 'N'].map((v) => {
          const sel = value === v;
          const c = v === 'Y' ? '#22a06b' : '#e5484d';
          return (
            <button key={v} type="button" onClick={() => onChange(v)} className="btn btn-sm"
              style={{ width: 46, justifyContent: 'center', border: '1.5px solid ' + (sel ? c : 'var(--border-input, #d6e0d2)'), background: sel ? c + '22' : 'var(--bg-card, #fff)', color: sel ? c : T_SECONDARY, fontWeight: 700 }}>{v}</button>
          );
        })}
      </div>
    </div>
  );
}

function CloseModal({ job, timers, onCancel, onConfirm, busy }) {
  const step = Number(jobStep(job)) || 0;
  const isTempering = TEMPERING_STEPS.includes(step);
  const isWidth = WIDTH_STEPS.includes(step);
  const isThickness = THICKNESS_STEPS.includes(step);
  const isFinal = step === FINAL_STEP;
  const isMeasureStep = isWidth || isThickness || isFinal;

  const [qc, setQc] = useState('No QC check for this step');
  const [measured, setMeasured] = useState('');
  const [result, setResult] = useState('Pass');
  const [notes, setNotes] = useState('');
  const [temp, setTemp] = useState('');
  const [soak, setSoak] = useState('');
  const [width, setWidth] = useState('');
  const [thickness, setThickness] = useState('');
  const [hrc, setHrc] = useState('');
  const [designOk, setDesignOk] = useState('Y');
  const [cycleOk, setCycleOk] = useState('Y');
  const [htOk, setHtOk] = useState('Y');

  const hasQc = qc !== 'No QC check for this step';
  const nextStep = step ? step + 1 : null;

  const widthHint = toleranceHint('width', width);
  const thicknessHint = toleranceHint('thickness', thickness);

  const valid =
    (!hasQc || measured.trim()) &&
    (!isTempering || (temp.trim() && soak.trim())) &&
    (!isWidth || width.trim()) &&
    (!isThickness || thickness.trim()) &&
    (!isFinal || (width.trim() && thickness.trim() && hrc.trim()));

  const pauses = pick(job, 'pause_count', 'pauses', 'pause_cycles');
  const totalElapsed = pick(job, 'total_elapsed_seconds', 'elapsed_seconds');

  function submit() {
    const payload = { notes: notes.trim() || null };
    if (isTempering) {
      payload.actual_temperature = temp.trim();
      payload.actual_soak_time = soak.trim();
    }
    if (isFinal) {
      // §23 — Final Inspection: the backend evaluates BOTH width and thickness
      // against tolerance and gates on the confirmations (worst outcome wins).
      payload.qc_check = 'Final Inspection';
      payload.width_mm = width.trim();
      payload.thickness_mm = thickness.trim();
      payload.hrc_value = hrc.trim();
      payload.design_confirmed = designOk;
      payload.cycle_confirmed = cycleOk;
      payload.ht_confirmed = htOk;
      payload.notes = `FINAL — Design:${designOk} Cycle:${cycleOk} HT:${htOk}${notes.trim() ? ' · ' + notes.trim() : ''}`;
    } else if (isWidth) {
      payload.qc_check = 'Width (mm)';
      payload.measured_value = width.trim();
      payload.qc_result = widthHint ? (widthHint.status === 'pass' ? 'Pass' : 'Fail') : 'Pass';
    } else if (isThickness) {
      payload.qc_check = 'Thickness (mm)';
      payload.measured_value = thickness.trim();
      payload.thicknessMm = thickness.trim();
      payload.qc_result = thicknessHint ? (thicknessHint.status === 'pass' ? 'Pass' : 'Fail') : 'Pass';
    } else if (hasQc) {
      payload.qc_check = qc;
      payload.measured_value = measured.trim();
      payload.qc_result = result;
    }
    onConfirm(payload);
  }

  return (
    <Modal title={`Close job — ${pick(job, 'uid', 'uid_code', 'code')} · Step ${step}`} onClose={busy ? () => {} : onCancel} width={560}>
      <div className="card" style={{ background: 'var(--bg-muted, #f4f7f2)', boxShadow: 'none', padding: '14px 16px', marginBottom: 18 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
          <Label>Net work time</Label>
          <Mono style={{ fontWeight: 700, color: T_PRIMARY }}>{fmtHMS(timers.net)}</Mono>
        </div>
        {totalElapsed != null && (
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
            <Label>Total elapsed (incl. pauses)</Label>
            <Mono style={{ color: T_SECONDARY }}>{fmtHMS(totalElapsed)}</Mono>
          </div>
        )}
        {pauses != null && (
          <div style={{ display: 'flex', justifyContent: 'space-between' }}>
            <Label>Pauses</Label>
            <Mono style={{ color: T_SECONDARY }}>{pauses}</Mono>
          </div>
        )}
      </div>

      {isTempering && (
        <div style={{ marginBottom: 18 }}>
          <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 13, color: T_PRIMARY, marginBottom: 4 }}>Tempering reading — required</div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <div>
              <label className="form-label">Actual temperature (°C)</label>
              <input className="form-input" value={temp} onChange={(e) => setTemp(e.target.value)} inputMode="decimal" />
            </div>
            <div>
              <label className="form-label">Actual soak time (min)</label>
              <input className="form-input" value={soak} onChange={(e) => setSoak(e.target.value)} inputMode="decimal" />
            </div>
          </div>
        </div>
      )}

      {/* §23 — Width measurement (Bunch/Angle Grinding) */}
      {isWidth && !isFinal && (
        <div style={{ marginBottom: 18 }}>
          <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 13, color: T_PRIMARY, marginBottom: 6 }}>Quality check — Width</div>
          <label className="form-label">Measured width (mm)</label>
          <input className="form-input" value={width} onChange={(e) => setWidth(e.target.value)} inputMode="decimal" autoFocus placeholder="target 180mm · pass 180–182mm" />
          <ToleranceChip hint={widthHint} />
        </div>
      )}

      {/* §23 — Thickness measurement (OP10, Surface Grind 1 & 2) */}
      {isThickness && !isFinal && (
        <div style={{ marginBottom: 18 }}>
          <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 13, color: T_PRIMARY, marginBottom: 6 }}>Quality check — Thickness</div>
          <div style={{ fontFamily: SANS, fontSize: 12, color: T_SECONDARY, marginBottom: 8 }}>
            {[12, 20].includes(step) ? 'Measure with the VCL gauge at this workstation — no trip to the inspection table.' : 'Record thickness at this milling step.'}
          </div>
          <label className="form-label">Measured thickness (mm)</label>
          <input className="form-input" value={thickness} onChange={(e) => setThickness(e.target.value)} inputMode="decimal" autoFocus placeholder="target 16mm · pass 16–16.5mm" />
          <ToleranceChip hint={thicknessHint} />
        </div>
      )}

      {/* §23 — Final Inspection (HRC-01): full dimensional + confirmations */}
      {isFinal && (
        <div style={{ marginBottom: 18 }}>
          <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 13, color: T_PRIMARY, marginBottom: 6 }}>Final Inspection — all fields required</div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <div>
              <label className="form-label">Width (mm)</label>
              <input className="form-input" value={width} onChange={(e) => setWidth(e.target.value)} inputMode="decimal" placeholder="180–182" />
              <ToleranceChip hint={widthHint} />
            </div>
            <div>
              <label className="form-label">Thickness (mm)</label>
              <input className="form-input" value={thickness} onChange={(e) => setThickness(e.target.value)} inputMode="decimal" placeholder="16–16.5" />
              <ToleranceChip hint={thicknessHint} />
            </div>
          </div>
          <div style={{ marginTop: 12, maxWidth: 200 }}>
            <label className="form-label">HRC measured</label>
            <input className="form-input" value={hrc} onChange={(e) => setHrc(e.target.value)} inputMode="decimal" placeholder="target 60–64" />
          </div>
          <div style={{ marginTop: 12, borderTop: '1px solid var(--border-card, #e3ebde)', paddingTop: 6 }}>
            <YesNo label="Design confirmed" value={designOk} onChange={setDesignOk} />
            <YesNo label="Cycle confirmed" value={cycleOk} onChange={setCycleOk} />
            <YesNo label="Heat-treatment parameters met" value={htOk} onChange={setHtOk} />
          </div>
        </div>
      )}

      {/* Generic QC prompt only for non-measurement, non-tempering steps */}
      {!isMeasureStep && !isTempering && (
        <>
          <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 13, color: T_PRIMARY, marginBottom: 8 }}>QC check required at this step?</div>
          {QC_OPTIONS.map((o) => (
            <RadioRow key={o} name="qc-check" value={o} current={qc} onChange={setQc}>{o}</RadioRow>
          ))}
          {hasQc && (
            <div style={{ marginTop: 6 }}>
              <div style={{ marginBottom: 12 }}>
                <label className="form-label">Measured value</label>
                <input className="form-input" value={measured} onChange={(e) => setMeasured(e.target.value)} />
              </div>
              <label className="form-label">Result</label>
              <div style={{ display: 'flex', gap: 8, marginBottom: 4 }}>
                {['Pass', 'Fail', 'Borderline'].map((r) => {
                  const sel = result === r;
                  const c = r === 'Pass' ? '#22a06b' : r === 'Fail' ? '#e5484d' : '#f0a020';
                  return (
                    <button key={r} type="button" onClick={() => setResult(r)} className="btn"
                      style={{ height: 44, flex: 1, justifyContent: 'center', border: '1.5px solid ' + (sel ? c : 'var(--border-input, #d6e0d2)'), background: sel ? c + '22' : 'var(--bg-card, #fff)', color: sel ? c : T_SECONDARY, fontWeight: 700 }}>{r}</button>
                  );
                })}
              </div>
            </div>
          )}
        </>
      )}

      <div style={{ marginTop: 14 }}>
        <label className="form-label">Notes (optional)</label>
        <textarea className="form-input" value={notes} onChange={(e) => setNotes(e.target.value)} rows={2} style={{ height: 'auto', padding: 11, resize: 'vertical' }} />
      </div>

      {(widthHint?.status === 'concession' || thicknessHint?.status === 'concession') && (
        <div style={{ marginTop: 12, padding: '10px 13px', borderRadius: 9, background: 'var(--bg-soft-amber, #fdf6ef)', color: '#8a5a1a', fontFamily: SANS, fontSize: 12 }}>
          Below minimum — closing raises a concession request for Manager/Admin approval; the piece is held meanwhile.
        </div>
      )}
      {(widthHint?.status === 'reject' || thicknessHint?.status === 'reject') && (
        <div style={{ marginTop: 12, padding: '10px 13px', borderRadius: 9, background: 'rgba(229,72,77,0.08)', color: 'var(--status-danger-dark, #c0392b)', fontFamily: SANS, fontSize: 12 }}>
          Above maximum — reject: the piece is returned for further grinding (no concession).
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 10, marginTop: 20 }}>
        <button className="btn" style={{ height: 48, padding: '0 22px' }} onClick={onCancel} disabled={busy}>Cancel</button>
        <button className="btn btn-primary" style={{ height: 48, padding: '0 22px' }} disabled={!valid || busy} onClick={submit}>
          <Icon name="check" size={16} />
          {busy ? 'Closing…' : nextStep ? `Confirm close — advance to step ${nextStep}` : 'Confirm close'}
        </button>
      </div>
    </Modal>
  );
}

/* ── Generate UID modal (TAG-01 / Tagging Table operator) ────────────────────
   UID creation is just an operation the receiving operator performs: they take a
   cycle, a quantity and (optionally) a raw-material size, and the system mints the
   codes at step 1 (RM-Q). No admin needed — this is the genesis of every job. */

function GenerateUidModal({ onClose, onDone }) {
  const [cycles, setCycles] = useState(null);
  const [sizes, setSizes] = useState([]);
  const [cycleCode, setCycleCode] = useState('');
  const [quantity, setQuantity] = useState('1');
  const [sizeId, setSizeId] = useState('');
  const [priority, setPriority] = useState('Normal');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [created, setCreated] = useState(null); // string[] of minted codes

  useEffect(() => {
    let live = true;
    Promise.all([cyclesApi.list(), masterApi.sizes().catch(() => ({ data: [] }))])
      .then(([c, s]) => {
        if (!live) return;
        const rows = (c?.data || []).filter((r) => (r.status || 'active') !== 'archived');
        setCycles(rows);
        setSizes(s?.data || []);
        if (rows[0]) setCycleCode(rows[0].code);
      })
      .catch(() => live && setCycles([]));
    return () => { live = false; };
  }, []);

  const qtyNum = Math.max(0, parseInt(quantity, 10) || 0);
  const valid = cycleCode && qtyNum >= 1 && qtyNum <= 5000;

  async function submit() {
    if (!valid) return;
    setBusy(true);
    setError(null);
    try {
      const res = await uidsApi.bulkCreate({
        cycleCode,
        quantity: qtyNum,
        sizeId: sizeId ? Number(sizeId) : undefined,
        priority,
      });
      setCreated(res?.data?.created || []);
      onDone?.();
    } catch (err) {
      setError(err?.message || 'Could not generate UIDs — please try again.');
    } finally {
      setBusy(false);
    }
  }

  if (created) {
    return (
      <Modal title={`UIDs generated — ${created.length}`} onClose={onClose} width={520}>
        <div style={{ fontFamily: SANS, fontSize: 13, color: T_SECONDARY, marginBottom: 12 }}>
          {created.length} new {created.length === 1 ? 'UID has' : 'UIDs have'} been created at step 1 (RM-Q) and are now in the receiving queue.
        </div>
        <div className="card" style={{ background: 'var(--bg-muted, #f4f7f2)', boxShadow: 'none', padding: '12px 14px', maxHeight: 220, overflowY: 'auto' }}>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
            {created.map((code) => (
              <Mono key={code} style={{ fontSize: 12, fontWeight: 700, color: T_PRIMARY, background: 'var(--bg-card, #fff)', border: '1px solid var(--border-card, #e3ebde)', borderRadius: 7, padding: '4px 9px' }}>
                {code}
              </Mono>
            ))}
          </div>
        </div>
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 10, marginTop: 18 }}>
          <button className="btn" style={{ height: 48, padding: '0 22px' }} onClick={() => { setCreated(null); setError(null); }}>Generate more</button>
          <button className="btn btn-primary" style={{ height: 48, padding: '0 22px' }} onClick={onClose}>Done</button>
        </div>
      </Modal>
    );
  }

  return (
    <Modal title="Generate UID — Tagging Table" onClose={busy ? () => {} : onClose} width={520}>
      <div style={{ fontFamily: SANS, fontSize: 12.5, color: T_SECONDARY, marginBottom: 16 }}>
        Tag the cut plates at the Tagging Table — mint a UID for each. Each UID enters the cycle and flows to its next step.
      </div>

      <div style={{ marginBottom: 14 }}>
        <label className="form-label">Cycle</label>
        {cycles === null ? (
          <div style={{ fontFamily: SANS, fontSize: 13, color: T_MUTED }}>Loading cycles…</div>
        ) : (
          <select className="form-input" value={cycleCode} onChange={(e) => setCycleCode(e.target.value)} disabled={busy}>
            {cycles.length === 0 && <option value="">No cycles available</option>}
            {cycles.map((c) => (
              <option key={c.code} value={c.code}>{c.code} — {c.name}</option>
            ))}
          </select>
        )}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginBottom: 14 }}>
        <div>
          <label className="form-label">Quantity</label>
          <input
            className="form-input"
            value={quantity}
            onChange={(e) => setQuantity(e.target.value.replace(/[^0-9]/g, ''))}
            inputMode="numeric"
            disabled={busy}
          />
        </div>
        <div>
          <label className="form-label">Priority</label>
          <select className="form-input" value={priority} onChange={(e) => setPriority(e.target.value)} disabled={busy}>
            {['Normal', 'High', 'Urgent'].map((p) => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>
      </div>

      <div style={{ marginBottom: 6 }}>
        <label className="form-label">Raw-material size (optional)</label>
        <select className="form-input" value={sizeId} onChange={(e) => setSizeId(e.target.value)} disabled={busy}>
          <option value="">— not specified —</option>
          {sizes.map((s) => (
            <option key={s.id} value={s.id}>{s.size_mm} mm{s.description ? ` · ${s.description}` : ''}</option>
          ))}
        </select>
      </div>

      {error && (
        <div style={{ marginTop: 14, padding: '10px 13px', borderRadius: 9, background: 'var(--bg-soft-amber, #fdf6ef)', color: 'var(--status-danger-dark, #c0392b)', fontFamily: SANS, fontSize: 12 }}>
          {error}
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 10, marginTop: 20 }}>
        <button className="btn" style={{ height: 48, padding: '0 22px' }} onClick={onClose} disabled={busy}>Cancel</button>
        <button className="btn btn-primary" style={{ height: 48, padding: '0 22px' }} disabled={!valid || busy} onClick={submit}>
          <Icon name="tag" size={16} />
          {busy ? 'Generating…' : `Generate ${qtyNum || ''} UID${qtyNum === 1 ? '' : 's'}`.trim()}
        </button>
      </div>
    </Modal>
  );
}

/* ── Active job card ─────────────────────────────────────────────────────── */

function ActiveJobCard({ job, nowMs, canAct, canHold, onStart, onPause, onResume, onClose, onHold, pendingAction }) {
  const timers = computeTimers(job, nowMs);
  const status = timers.status;
  const running = status === 'in_progress' || status === 'running' || status === 'active';
  const paused = status === 'paused';
  const accent = dotColor(status);

  const uid = pick(job, 'uid', 'uid_code', 'code');
  const step = jobStep(job);
  const opName = pick(job, 'operation', 'operation_name', 'step_name');
  const station = pick(job, 'workstation_name', 'unit_name', 'workstation_code', 'unit_code', 'workstation', 'station', 'station_code', 'unit');
  const cycle = pick(job, 'cycle', 'cycle_type');
  const length = pick(job, 'length', 'length_mm');
  const finish = pick(job, 'finish', 'pattern', 'finish_type');
  const mo = pick(job, 'mo', 'mo_number', 'manufacturing_order');
  const priority = pick(job, 'priority');
  const collectFrom = pick(job, 'collect_from', 'source_storage', 'collect_storage', 'source_location');
  const deliverTo = pick(job, 'deliver_to', 'destination_storage', 'deliver_storage', 'dest_location');
  const pauseReason = pick(job, 'pause_reason', 'last_pause_reason');

  const busy = !!pendingAction;

  return (
    <div className="card" style={{ padding: 0, overflow: 'hidden', borderLeft: `4px solid ${accent}` }}>
      <div style={{ padding: '18px 22px' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap' }}>
          <StatusPill status={paused ? 'paused' : running ? 'in_progress' : status} label={paused && pauseReason ? `PAUSED — ${pauseReason}` : undefined} />
          <Mono style={{ fontSize: 11, color: T_SECONDARY }}>
            {pick(job, 'shift', 'shift_name', 'shift_number') ? `Shift ${pick(job, 'shift', 'shift_name', 'shift_number')} · ` : ''}{station || ''}
          </Mono>
        </div>

        <div style={{ marginTop: 12, lineHeight: 1 }}>
          {uid
            ? <EntityLink to={routes.uid(uid)} title="Open UID detail" style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 34, letterSpacing: '-0.03em', color: T_PRIMARY }}>{uid}</EntityLink>
            : <span style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 34, letterSpacing: '-0.03em', color: T_PRIMARY }}>—</span>}
        </div>
        <div style={{ fontFamily: SANS, fontSize: 13, color: T_SECONDARY, marginTop: 6 }}>
          {[opName, station, step != null ? `Step ${step}` : null].filter(Boolean).join(' · ')}
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', marginTop: 10 }}>
          {cycle && <CycleBadge cycle={cycle} />}
          {length != null && <Mono style={{ fontSize: 11, color: T_SECONDARY }}>{length}{String(length).match(/mm$/) ? '' : 'mm'}</Mono>}
          {finish && <span style={{ fontFamily: SANS, fontSize: 12, color: T_SECONDARY }}>{finish}</span>}
          {mo && <Mono style={{ fontSize: 11, color: T_SECONDARY }}>{mo}</Mono>}
          {priority && <PriorityBadge priority={priority} />}
        </div>

        {(collectFrom || deliverTo) && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 12, fontFamily: MONO, fontSize: 12, color: T_PRIMARY }}>
            {collectFrom && <span><span style={{ color: T_MUTED }}>Collect from </span>{collectFrom}</span>}
            {collectFrom && deliverTo && <Icon name="chevronRight" size={14} color={T_MUTED} />}
            {deliverTo && <span><span style={{ color: T_MUTED }}>Deliver to </span>{deliverTo}</span>}
          </div>
        )}
      </div>

      {/* timers */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1, background: 'var(--border-card, #e3ebde)' }}>
        {paused ? (
          <>
            <TimerCell label="Paused for" value={fmtHMS(timers.paused)} color="#d97a2b" />
            <TimerCell label="Net work time so far" value={fmtHMS(timers.net)} color={T_PRIMARY} />
          </>
        ) : (
          <>
            <TimerCell label="Active time (since resume)" value={fmtHMS(timers.active)} color={accent} />
            <TimerCell label="Net work time" value={fmtHMS(timers.net)} color={T_PRIMARY} />
          </>
        )}
      </div>

      {step != null && (
        <div style={{ padding: '16px 22px', borderTop: '1px solid var(--border-card, #e3ebde)' }}>
          <Label style={{ marginBottom: 8 }}>Step progress</Label>
          <StepTrack step={step} />
        </div>
      )}

      {/* actions */}
      <div style={{ padding: '16px 22px', borderTop: '1px solid var(--border-card, #e3ebde)', display: 'flex', gap: 12, flexWrap: 'wrap' }}>
        {!canAct ? (
          <div style={{ fontFamily: SANS, fontSize: 12.5, color: T_SECONDARY }}>Read-only — you do not have permission to act on this job.</div>
        ) : running ? (
          <>
            <button className="btn" style={{ height: 56, flex: 1, minWidth: 160, justifyContent: 'center', fontSize: 14 }} disabled={busy} onClick={onPause}>
              <Icon name="pause" size={20} />{pendingAction === 'pause' ? 'Pausing…' : 'Pause'}
            </button>
            <button className="btn btn-primary" style={{ height: 56, flex: 1, minWidth: 160, justifyContent: 'center', fontSize: 14 }} disabled={busy} onClick={onClose}>
              <Icon name="check" size={20} />{pendingAction === 'close' ? 'Closing…' : 'Close job'}
            </button>
          </>
        ) : paused ? (
          <button className="btn btn-primary" style={{ height: 56, flex: 1, justifyContent: 'center', fontSize: 14 }} disabled={busy} onClick={onResume}>
            <Icon name="play" size={20} />{pendingAction === 'resume' ? 'Resuming…' : 'Resume job'}
          </button>
        ) : (
          <button className="btn btn-primary" style={{ height: 56, flex: 1, justifyContent: 'center', fontSize: 14 }} disabled={busy} onClick={onStart}>
            <Icon name="play" size={20} />{pendingAction === 'start' ? 'Starting…' : 'Start job'}
          </button>
        )}
        {/* §8 — Supervisors/Admins can HOLD an in-progress or paused job. */}
        {canAct && canHold && (running || paused) && (
          <button className="btn" style={{ height: 56, minWidth: 110, justifyContent: 'center', fontSize: 14, borderColor: '#e5484d', color: '#e5484d' }} disabled={busy} onClick={onHold}>
            <Icon name="lock" size={18} />{pendingAction === 'hold' ? 'Holding…' : 'Hold'}
          </button>
        )}
      </div>
    </div>
  );
}

function TimerCell({ label, value, color }) {
  return (
    <div style={{ background: 'var(--bg-card, #fff)', padding: '16px 22px' }}>
      <Label>{label}</Label>
      <div style={{ fontFamily: MONO, fontWeight: 600, fontSize: 30, color, marginTop: 6, lineHeight: 1 }}>{value}</div>
    </div>
  );
}

/* ── Bunch grinding (SG-DLT) ──────────────────────────────────────────────────
   For the SG-DLT bunch-grinding machine the operator manually LOADS several
   bars at once (a "bunch") onto the machine, runs them together, then closes
   the whole bunch. This panel REPLACES the single active-job card + queue for
   SG-DLT stations only. Bars in a single bunch must share one operation_name
   (the backend rejects mixed steps with STEP_MISMATCH).
   ──────────────────────────────────────────────────────────────────────────── */

function BunchBarRow({ uid, idx, selected, disabled, onToggle }) {
  return (
    <label
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: 12,
        padding: '12px 16px',
        borderTop: idx ? '1px solid var(--border-card, #e3ebde)' : 'none',
        cursor: disabled ? 'not-allowed' : 'pointer',
        opacity: disabled ? 0.45 : 1,
        background: selected ? 'var(--bg-soft-blue, #eaf0f7)' : 'transparent',
      }}
    >
      <input
        type="checkbox"
        checked={selected}
        disabled={disabled}
        onChange={onToggle}
        style={{ width: 18, height: 18, accentColor: '#3b82f6', flex: '0 0 auto' }}
      />
      <div style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 15, letterSpacing: '-0.02em', color: T_PRIMARY, minWidth: 64 }}>
        {pick(uid, 'uid_code') || pick(uid, 'uid_id')}
      </div>
      {pick(uid, 'operation_name') && (
        <span
          style={{
            fontFamily: MONO,
            fontSize: 9.5,
            letterSpacing: '0.06em',
            textTransform: 'uppercase',
            color: T_SECONDARY,
            background: 'var(--bg-muted, #f4f7f2)',
            border: '1px solid var(--border-card, #e3ebde)',
            borderRadius: 6,
            padding: '3px 7px',
          }}
        >
          {pick(uid, 'operation_name')}
        </span>
      )}
      <div style={{ flex: 1 }} />
      {pick(uid, 'size_mm') != null && (
        <Mono style={{ fontSize: 12, color: T_SECONDARY }}>{pick(uid, 'size_mm')}mm</Mono>
      )}
      {pick(uid, 'storage_code') && (
        <Mono style={{ fontSize: 11, color: T_MUTED }}>{pick(uid, 'storage_code')}</Mono>
      )}
    </label>
  );
}

function BunchGrindingPanel({ unitId, nowMs, canAct }) {
  const { data: activeData, refetch: refetchActive } = usePolling(
    () => (unitId == null ? Promise.resolve(null) : batchesApi.grindingActiveBatch(unitId).then((r) => r.data)),
    [unitId],
    { interval: 20000 }
  );
  const { data: queueData, refetch: refetchQueue } = usePolling(
    () => batchesApi.grindingQueue().then((r) => r.data),
    [],
    { interval: 20000 }
  );

  const activeBatch = activeData || null;
  const bedLengthMm = pick(queueData || {}, 'bedLengthMm');
  const queueUids = useMemo(() => (queueData && Array.isArray(queueData.uids) ? queueData.uids : []), [queueData]);

  const [selected, setSelected] = useState({}); // uid_id -> true
  const [selectedOp, setSelectedOp] = useState(null); // the operation_name the current selection is locked to
  const [busy, setBusy] = useState(false);
  const [opError, setOpError] = useState(null);

  // Clear any stale selection if the underlying queue no longer contains it.
  useEffect(() => {
    setSelected((prev) => {
      const next = {};
      for (const u of queueUids) {
        const id = String(pick(u, 'uid_id'));
        if (prev[id]) next[id] = true;
      }
      return next;
    });
  }, [queueUids]);

  const selectedIds = useMemo(() => Object.keys(selected).filter((k) => selected[k]), [selected]);
  const selectedCount = selectedIds.length;

  // Reset the operation lock once nothing is selected.
  useEffect(() => {
    if (selectedCount === 0 && selectedOp != null) setSelectedOp(null);
  }, [selectedCount, selectedOp]);

  const combinedLength = useMemo(() => {
    let sum = 0;
    for (const u of queueUids) {
      const id = String(pick(u, 'uid_id'));
      if (selected[id]) sum += Number(pick(u, 'size_mm')) || 0;
    }
    return sum;
  }, [queueUids, selected]);

  const overflow = bedLengthMm != null && combinedLength > Number(bedLengthMm);

  // Group queued bars by operation_name (bars in a bunch must share one step).
  const groups = useMemo(() => {
    const map = new Map();
    for (const u of queueUids) {
      const op = pick(u, 'operation_name') || 'Unspecified';
      if (!map.has(op)) map.set(op, []);
      map.get(op).push(u);
    }
    return Array.from(map.entries()); // [opName, uids[]]
  }, [queueUids]);

  function toggle(uid) {
    const id = String(pick(uid, 'uid_id'));
    const op = pick(uid, 'operation_name');
    setOpError(null);
    setSelected((prev) => {
      const next = { ...prev };
      if (next[id]) {
        delete next[id];
      } else {
        next[id] = true;
        if (selectedOp == null) setSelectedOp(op);
      }
      return next;
    });
  }

  async function load() {
    if (!selectedCount || overflow) return;
    setBusy(true);
    setOpError(null);
    try {
      await batchesApi.grindingLoadBatch(unitId, selectedIds);
      setSelected({});
      setSelectedOp(null);
      await Promise.all([refetchActive(), refetchQueue()]);
    } catch (err) {
      setOpError(err?.message || 'Could not load the bunch — please try again.');
    } finally {
      setBusy(false);
    }
  }

  async function closeBunch() {
    if (!activeBatch) return;
    setBusy(true);
    setOpError(null);
    try {
      await batchesApi.grindingCloseBatch(pick(activeBatch, 'id'));
      await Promise.all([refetchActive(), refetchQueue()]);
    } catch (err) {
      setOpError(err?.message || 'Could not close the bunch — please try again.');
    } finally {
      setBusy(false);
    }
  }

  /* ── Active bunch on the machine ── */
  if (activeBatch) {
    const bars = Array.isArray(pick(activeBatch, 'uids')) ? pick(activeBatch, 'uids') : [];
    const combined = pick(activeBatch, 'combined_length_mm');
    const elapsed = elapsedFrom(pick(activeBatch, 'started_at'), nowMs);
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 18 }}>
        {opError && (
          <div className="card" style={{ padding: '12px 16px', display: 'flex', alignItems: 'center', gap: 10, borderLeft: '4px solid var(--status-danger, #e5484d)' }}>
            <Icon name="alert" size={18} color="#e5484d" />
            <span style={{ fontFamily: SANS, fontSize: 13, color: 'var(--status-danger-dark, #c0392b)', flex: 1 }}>{opError}</span>
          </div>
        )}
        <div className="card" style={{ padding: 0, overflow: 'hidden', borderLeft: '4px solid #22a06b' }}>
          <div style={{ padding: '18px 22px' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap' }}>
              <StatusPill status="in_progress" label="BUNCH RUNNING" />
              <Mono style={{ fontSize: 11, color: T_SECONDARY }}>{pick(activeBatch, 'operation_name') || ''}</Mono>
            </div>
            <div style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 30, letterSpacing: '-0.03em', color: T_PRIMARY, marginTop: 12, lineHeight: 1 }}>
              {pick(activeBatch, 'batch_number') || 'Bunch'}
            </div>
            <div style={{ fontFamily: SANS, fontSize: 13, color: T_SECONDARY, marginTop: 6 }}>
              {bars.length} {bars.length === 1 ? 'bar' : 'bars'} loaded
            </div>
          </div>

          {/* loaded bars */}
          <div style={{ borderTop: '1px solid var(--border-card, #e3ebde)' }}>
            {bars.map((b, i) => (
              <div
                key={pick(b, 'uid_id') ?? i}
                style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '11px 22px', borderTop: i ? '1px solid var(--border-card, #e3ebde)' : 'none' }}
              >
                <Mono style={{ fontSize: 12, color: T_MUTED, width: 18 }}>{i + 1}.</Mono>
                <div style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 15, letterSpacing: '-0.02em', color: T_PRIMARY, minWidth: 64 }}>
                  {pick(b, 'uid_code') || pick(b, 'uid_id')}
                </div>
                {pick(b, 'set_number') != null && <Mono style={{ fontSize: 11, color: T_MUTED }}>Set {pick(b, 'set_number')}</Mono>}
                <div style={{ flex: 1 }} />
                {pick(b, 'size_mm') != null && <Mono style={{ fontSize: 12, color: T_SECONDARY }}>{pick(b, 'size_mm')}mm</Mono>}
              </div>
            ))}
          </div>

          {/* timers + bed usage */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1, background: 'var(--border-card, #e3ebde)', borderTop: '1px solid var(--border-card, #e3ebde)' }}>
            <TimerCell label="Running for" value={fmtHMS(elapsed)} color="#22a06b" />
            <div style={{ background: 'var(--bg-card, #fff)', padding: '16px 22px' }}>
              <Label>Bed usage</Label>
              <div style={{ fontFamily: MONO, fontWeight: 600, fontSize: 30, color: T_PRIMARY, marginTop: 6, lineHeight: 1 }}>
                {combined != null ? combined : '—'}{bedLengthMm != null ? ` / ${bedLengthMm}` : ''} mm
              </div>
            </div>
          </div>

          {/* actions */}
          <div style={{ padding: '16px 22px', borderTop: '1px solid var(--border-card, #e3ebde)', display: 'flex', gap: 12, flexWrap: 'wrap' }}>
            {!canAct ? (
              <div style={{ fontFamily: SANS, fontSize: 12.5, color: T_SECONDARY }}>Read-only — you do not have permission to act on this machine.</div>
            ) : (
              <button className="btn btn-primary" style={{ height: 56, flex: 1, justifyContent: 'center', fontSize: 14 }} disabled={busy} onClick={closeBunch}>
                <Icon name="check" size={20} />{busy ? 'Closing…' : 'Close bunch'}
              </button>
            )}
          </div>
        </div>
      </div>
    );
  }

  /* ── No active bunch: load one from the queue ── */
  const empty = queueUids.length === 0;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 18 }}>
      {opError && (
        <div className="card" style={{ padding: '12px 16px', display: 'flex', alignItems: 'center', gap: 10, borderLeft: '4px solid var(--status-danger, #e5484d)' }}>
          <Icon name="alert" size={18} color="#e5484d" />
          <span style={{ fontFamily: SANS, fontSize: 13, color: 'var(--status-danger-dark, #c0392b)', flex: 1 }}>{opError}</span>
        </div>
      )}

      <div className="card" style={{ padding: 28, textAlign: 'center' }}>
        <StatusPill status="idle" label="MACHINE EMPTY" />
        <div style={{ fontFamily: SANS, fontSize: 13, color: T_SECONDARY, marginTop: 10 }}>
          No bunch loaded. Select bars of the same operation below and load them together.
        </div>
      </div>

      <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
        <div style={{ padding: '14px 18px', borderBottom: empty ? 'none' : '1px solid var(--border-card, #e3ebde)', display: 'flex', alignItems: 'center', gap: 8 }}>
          <Icon name="list" size={16} color={T_SECONDARY} />
          <span style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 14, letterSpacing: '-0.02em', color: T_PRIMARY }}>
            Bars waiting for bunch grinding
          </span>
          <Mono style={{ fontSize: 11, color: T_MUTED }}>
            ({queueUids.length} {queueUids.length === 1 ? 'bar' : 'bars'})
          </Mono>
        </div>

        {empty ? (
          <div style={{ padding: '24px 18px', fontFamily: SANS, fontSize: 13, color: T_SECONDARY, textAlign: 'center' }}>
            No bars waiting for bunch grinding.
          </div>
        ) : (
          groups.map(([opName, uids], gi) => {
            // Once a selection has started, lock to that operation; others disabled.
            const opLocked = selectedOp != null && opName !== selectedOp;
            return (
              <div key={opName} style={{ borderTop: gi ? '4px solid var(--bg-muted, #f4f7f2)' : 'none' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '9px 16px', background: 'var(--bg-muted, #f4f7f2)' }}>
                  <Label style={{ color: T_SECONDARY }}>{opName}</Label>
                  <Mono style={{ fontSize: 10.5, color: T_MUTED }}>· {uids.length}</Mono>
                  {opLocked && (
                    <Mono style={{ fontSize: 10, color: T_MUTED, marginLeft: 'auto' }}>locked — different step</Mono>
                  )}
                </div>
                {uids.map((u, i) => {
                  const id = String(pick(u, 'uid_id'));
                  return (
                    <BunchBarRow
                      key={id ?? i}
                      uid={u}
                      idx={i}
                      selected={!!selected[id]}
                      disabled={!canAct || busy || (opLocked && !selected[id])}
                      onToggle={() => toggle(u)}
                    />
                  );
                })}
              </div>
            );
          })
        )}
      </div>

      {/* tally + load action */}
      {!empty && (
        <div className="card" style={{ padding: '16px 22px', display: 'flex', alignItems: 'center', gap: 16, flexWrap: 'wrap' }}>
          <div>
            <Label>Selected</Label>
            <div style={{ fontFamily: MONO, fontWeight: 700, fontSize: 16, color: overflow ? 'var(--status-danger, #e5484d)' : T_PRIMARY, marginTop: 4 }}>
              {selectedCount} {selectedCount === 1 ? 'bar' : 'bars'} · {combinedLength}{bedLengthMm != null ? ` / ${bedLengthMm}` : ''} mm
            </div>
            {overflow && (
              <div style={{ fontFamily: SANS, fontSize: 12, color: 'var(--status-danger-dark, #c0392b)', marginTop: 4 }}>
                Exceeds bed length — remove a bar before loading.
              </div>
            )}
          </div>
          <div style={{ flex: 1 }} />
          {canAct && (
            <button
              className="btn btn-primary"
              style={{ height: 52, minWidth: 220, justifyContent: 'center', fontSize: 14 }}
              disabled={busy || selectedCount === 0 || overflow}
              onClick={load}
            >
              <Icon name="play" size={18} />
              {busy ? 'Loading…' : `Load bunch (${selectedCount} ${selectedCount === 1 ? 'bar' : 'bars'} · ${combinedLength} mm)`}
            </button>
          )}
        </div>
      )}
    </div>
  );
}

/* ── Queue ───────────────────────────────────────────────────────────────── */

function QueueRow({ job, idx, nowMs, canAct, onStart, pending }) {
  const uid = pick(job, 'uid', 'uid_code', 'code');
  const length = pick(job, 'length', 'length_mm');
  const priority = pick(job, 'priority') || 'Normal';
  const waitSince = pick(job, 'queued_at', 'assigned_at', 'wait_since', 'created_at');
  const waitSecondsField = pick(job, 'wait_seconds', 'waiting_seconds');
  const wait = waitSecondsField != null ? Number(waitSecondsField) : elapsedFrom(waitSince, nowMs);

  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '13px 16px', borderTop: idx ? '1px solid var(--border-card, #e3ebde)' : 'none' }}>
      <Mono style={{ fontSize: 12, color: T_MUTED, width: 18 }}>{idx + 1}.</Mono>
      <div style={{ minWidth: 56 }}>
        <EntityLink to={uid ? routes.uid(uid) : null} title="Open UID detail" style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 15, letterSpacing: '-0.02em', color: T_PRIMARY }}>{uid || '—'}</EntityLink>
      </div>
      {length != null && <Mono style={{ fontSize: 11, color: T_SECONDARY }}>{length}{String(length).match(/mm$/) ? '' : 'mm'}</Mono>}
      <PriorityBadge priority={priority} />
      <div style={{ flex: 1 }} />
      <Mono style={{ fontSize: 12, color: T_SECONDARY }} title="Waiting">{fmtHMS(wait)}</Mono>
      {canAct && (
        <button className="btn btn-sm" style={{ height: 40 }} disabled={!!pending} onClick={onStart}>
          <Icon name="play" size={15} />{pending ? 'Starting…' : 'Start'}
        </button>
      )}
    </div>
  );
}

/* ── Admin oversight: all working workstations ───────────────────────────────
   Admins aren't assigned to a station, so instead of a personal queue they get
   an overview of every workstation that has work: the count of UIDs pending at
   that station, plus any live operator jobs (with timers) assigned there. */
function StationOversightCard({ row, nowMs, onClick }) {
  return (
    <div className="card" onClick={onClick} title="View workstation detail" style={{ padding: 16, display: 'flex', flexDirection: 'column', gap: 10, cursor: 'pointer' }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 10 }}>
        <div>
          <div style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 15, color: T_PRIMARY }}>{row.name}</div>
          {row.name !== row.code && <div style={{ fontFamily: MONO, fontSize: 10.5, color: T_MUTED }}>{row.code}</div>}
        </div>
        <span style={{ fontFamily: MONO, fontSize: 11, fontWeight: 700, color: row.pending ? T_PRIMARY : T_MUTED, background: 'var(--bg-muted, #eef2f7)', borderRadius: 20, padding: '3px 10px', whiteSpace: 'nowrap' }}>
          {row.pending} waiting
        </span>
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        {row.jobs.length === 0 ? (
          <div style={{ fontFamily: SANS, fontSize: 12, color: T_MUTED }}>No operator assigned</div>
        ) : row.jobs.map((j) => {
          const running = jobStatus(j) === 'in_progress';
          const secs = serverNetSeconds(j) + (running ? elapsedFrom(pick(j, 'started_at'), nowMs) : 0);
          return (
            <div key={jobId(j)} style={{ display: 'flex', alignItems: 'center', gap: 8, fontFamily: SANS, fontSize: 12.5 }}>
              <StatusPill status={jobStatus(j)} />
              <span style={{ color: T_PRIMARY, fontWeight: 600 }}>{pick(j, 'operator_name', 'operator') || 'Unassigned'}</span>
              {pick(j, 'uid_code', 'uid') && <span style={{ color: T_SECONDARY, fontFamily: MONO, fontSize: 11 }}>{pick(j, 'uid_code', 'uid')}</span>}
              {jobStep(j) != null && <span style={{ color: T_MUTED, fontFamily: MONO, fontSize: 11 }}>· Step {jobStep(j)}</span>}
              {running && <span style={{ marginLeft: 'auto', fontFamily: MONO, fontSize: 11, fontWeight: 700, color: T_PRIMARY }}>{fmtHMS(secs)}</span>}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function StatChip({ label, value }) {
  return (
    <div className="card" style={{ padding: '10px 16px', minWidth: 120 }}>
      <div style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 22, color: T_PRIMARY, lineHeight: 1 }}>{value}</div>
      <div style={{ fontFamily: MONO, fontSize: 10, letterSpacing: '0.06em', color: T_SECONDARY, marginTop: 5 }}>{label.toUpperCase()}</div>
    </div>
  );
}

/* Right-hand detail drawer for a workstation on the oversight board — mirrors
   the Production Floor drawer: who is active, on which UID, plus the assignment. */
function OversightDrawer({ row, nowMs, onClose }) {
  const jobs = row.jobs || [];
  const active = jobs.filter((j) => jobStatus(j) === 'in_progress');
  const others = jobs.filter((j) => jobStatus(j) !== 'in_progress');
  const operators = new Set(jobs.map((j) => pick(j, 'operator_name', 'operator')).filter(Boolean)).size;

  const Row = ({ j }) => {
    const running = jobStatus(j) === 'in_progress';
    const secs = serverNetSeconds(j) + (running ? elapsedFrom(pick(j, 'started_at'), nowMs) : 0);
    return (
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '9px 0', borderBottom: '1px solid var(--border-card, #eef2f7)', fontFamily: SANS, fontSize: 12.5 }}>
        <StatusPill status={jobStatus(j)} />
        <span style={{ color: T_PRIMARY, fontWeight: 600 }}>{pick(j, 'operator_name', 'operator') || 'Unassigned'}</span>
        {pick(j, 'uid_code', 'uid') && <span style={{ fontFamily: MONO, fontSize: 11, color: T_SECONDARY }}>{pick(j, 'uid_code', 'uid')}</span>}
        {jobStep(j) != null && <span style={{ fontFamily: MONO, fontSize: 11, color: T_MUTED }}>· Step {jobStep(j)}</span>}
        {running && <span style={{ marginLeft: 'auto', fontFamily: MONO, fontSize: 11, fontWeight: 700, color: T_PRIMARY }}>{fmtHMS(secs)}</span>}
      </div>
    );
  };

  return (
    <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(15,30,50,0.35)', zIndex: 60, display: 'flex', justifyContent: 'flex-end' }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: 'min(420px, 92vw)', height: '100%', background: 'var(--bg-card, #fff)', borderLeft: '1px solid var(--border-card, #e6ecf3)', boxShadow: '-8px 0 30px rgba(0,0,0,0.12)', overflowY: 'auto', padding: '20px 22px 40px' }}>
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 10 }}>
          <div>
            <div style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 19, color: T_PRIMARY }}>{row.name}</div>
            {row.name !== row.code && <div style={{ fontFamily: MONO, fontSize: 11.5, color: T_SECONDARY, marginTop: 2 }}>{row.code}</div>}
          </div>
          <button className="btn btn-sm" type="button" onClick={onClose}><Icon name="close" size={14} /></button>
        </div>

        <div style={{ display: 'flex', gap: 10, marginTop: 14 }}>
          <StatChip label="UIDs waiting" value={row.pending} />
          <StatChip label="In progress" value={active.length} />
          <StatChip label="Operators" value={operators} />
        </div>

        {active.length > 0 && (
          <div className="card" style={{ marginTop: 16, padding: '12px 14px', boxShadow: 'none', background: 'var(--bg-muted, #f4f7f2)', borderLeft: '4px solid var(--status-success, #22a06b)' }}>
            <Label style={{ marginBottom: 8 }}>Active now</Label>
            {active.map((j) => {
              const secs = serverNetSeconds(j) + elapsedFrom(pick(j, 'started_at'), nowMs);
              return (
                <div key={jobId(j)} style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 4 }}>
                  <Icon name="user" size={14} color={T_SECONDARY} />
                  <div style={{ display: 'flex', flexDirection: 'column', lineHeight: 1.25 }}>
                    <span style={{ fontFamily: SANS, fontSize: 13, fontWeight: 700, color: T_PRIMARY }}>{pick(j, 'operator_name', 'operator') || 'Unassigned'}</span>
                    <span style={{ fontFamily: MONO, fontSize: 11, color: T_SECONDARY }}>
                      {pick(j, 'uid_code', 'uid') || '— no UID —'}
                      {jobStep(j) != null ? ` · Step ${jobStep(j)}` : ''}
                      {pick(j, 'operation', 'operation_name') ? ` · ${pick(j, 'operation', 'operation_name')}` : ''}
                    </span>
                  </div>
                  <span style={{ marginLeft: 'auto', fontFamily: MONO, fontSize: 13, fontWeight: 700, color: 'var(--status-success-dark, #1c7a52)' }}>{fmtHMS(secs)}</span>
                </div>
              );
            })}
          </div>
        )}

        <Label style={{ marginTop: 20, marginBottom: 6 }}>Assigned jobs</Label>
        {jobs.length === 0 ? <div style={{ fontFamily: SANS, fontSize: 12, color: T_MUTED }}>No operator assigned.</div> : (
          <>
            {active.map((j) => <Row key={jobId(j)} j={j} />)}
            {others.map((j) => <Row key={jobId(j)} j={j} />)}
          </>
        )}
      </div>
    </div>
  );
}

function AllWorkstationsBoard() {
  const nowMs = useNow(true);
  const [selectedCode, setSelectedCode] = useState(null);
  const { data, loading, error, refetch } = usePolling(
    () => Promise.all([
      uidsApi.stationSummary().then((r) => r.data).catch(() => []),
      jobsApi.list({}).then((r) => r.data).catch(() => []),
    ]).then(([stations, jobs]) => ({ stations, jobs })),
    []
  );

  const stations = Array.isArray(data?.stations) ? data.stations : [];
  const jobsRaw = data?.jobs;
  const jobs = Array.isArray(jobsRaw) ? jobsRaw : (jobsRaw?.jobs || jobsRaw?.items || []);

  const jobsByCode = useMemo(() => {
    const m = new Map();
    for (const j of jobs) {
      const code = pick(j, 'workstation_type_code', 'workstation_code', 'unit_code') || '—';
      if (!m.has(code)) m.set(code, []);
      m.get(code).push(j);
    }
    return m;
  }, [jobs]);

  const board = useMemo(() => {
    const rows = stations.map((s) => ({ code: s.code, name: s.name || s.code, pending: Number(s.active_count) || 0, jobs: jobsByCode.get(s.code) || [] }));
    for (const [code, js] of jobsByCode) if (!rows.some((r) => r.code === code)) rows.push({ code, name: code, pending: 0, jobs: js });
    return rows.filter((r) => r.pending > 0 || r.jobs.length > 0).sort((a, b) => b.pending - a.pending || String(a.code).localeCompare(String(b.code)));
  }, [stations, jobsByCode]);

  const totalPending = board.reduce((n, r) => n + r.pending, 0);
  const totalActiveJobs = jobs.filter((j) => jobStatus(j) === 'in_progress').length;

  if (error && !data) {
    return (
      <div className="card" style={{ marginTop: 20, padding: 28, textAlign: 'center' }}>
        <div style={{ fontFamily: SANS, fontSize: 14, color: 'var(--status-danger-dark, #c0392b)' }}>{error.message || 'Could not load workstations.'}</div>
        <button className="btn btn-primary" style={{ marginTop: 14 }} onClick={refetch}><Icon name="refresh" size={16} />Retry</button>
      </div>
    );
  }

  return (
    <>
      <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', marginTop: 20 }}>
        <StatChip label="Working stations" value={board.length} />
        <StatChip label="UIDs waiting" value={totalPending} />
        <StatChip label="Jobs in progress" value={totalActiveJobs} />
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 14, marginTop: 16 }}>
        {board.map((r) => <StationOversightCard key={r.code} row={r} nowMs={nowMs} onClick={() => setSelectedCode(r.code)} />)}
      </div>
      {board.length === 0 && (
        <div className="card" style={{ marginTop: 16, padding: 40, textAlign: 'center', fontFamily: SANS, fontSize: 13, color: T_SECONDARY }}>
          {loading ? 'Loading workstations…' : 'No workstations have work right now.'}
        </div>
      )}
      {selectedCode && (() => {
        const r = board.find((b) => b.code === selectedCode);
        return r ? <OversightDrawer row={r} nowMs={nowMs} onClose={() => setSelectedCode(null)} /> : null;
      })()}
    </>
  );
}

/* ── Page ────────────────────────────────────────────────────────────────── */

const ACTIVE_STATUSES = ['in_progress', 'running', 'active', 'paused'];

/* §8 — swap-pool slot banner: the operator's current/next rotation slot with a
   5-minute pre-slot cue and a takeover confirmation. */
function SwapSlotBanner() {
  const { data, refetch } = usePolling(() => swapApi.mySlots().then((r) => r.data).catch(() => []), [], { interval: 30000 });
  const slots = Array.isArray(data) ? data : [];
  const [busy, setBusy] = useState(null);
  if (!slots.length) return null;
  const active = slots.find((s) => s.active);
  const next = slots.find((s) => !s.active);
  const t = (v) => new Date(v).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  async function confirm(id) {
    setBusy(id);
    try { await swapApi.confirmSlot(id); await refetch(); } finally { setBusy(null); }
  }
  return (
    <div className="card" style={{ marginTop: 16, padding: '12px 16px', borderLeft: '4px solid #2d6fb5', display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
      <Icon name="timer" size={18} color="#2d6fb5" />
      <div style={{ flex: 1, fontFamily: SANS, fontSize: 13, color: T_PRIMARY }}>
        {active
          ? <>You're on <b>{active.ws_code}</b> now{active.is_fixed ? ' (fixed INSP)' : ''} — until {t(active.ends_at)}.</>
          : next
            ? <>Next swap: <b>{next.ws_code}</b> at {t(next.starts_at)}{next.notify_soon ? ' — starting soon' : ''}.</>
            : null}
      </div>
      {active && !active.confirmed_at && !active.is_fixed && (
        <button className="btn btn-sm btn-primary" disabled={busy === active.id} onClick={() => confirm(active.id)}>Confirm takeover</button>
      )}
      {!active && next && next.notify_soon && !next.confirmed_at && (
        <button className="btn btn-sm" disabled={busy === next.id} onClick={() => confirm(next.id)}>Confirm upcoming</button>
      )}
    </div>
  );
}

export default function MyWorkstation() {
  const { user, isOperator, isSupervisor, isAdmin, isManager } = useAuth();
  const canAct = isOperator || isSupervisor || isAdmin; // Manager view is read-only
  const nowMs = useNow(true);

  const selfId = pick(user || {}, 'id', 'user_id', 'operator_id');

  // Oversight roles (admin/manager/supervisor) can either see the whole floor
  // ("All") or step into any operator's exact workstation view ("Individual").
  const isOversight = isAdmin || isManager || isSupervisor;
  const [view, setView] = useState('all');            // 'all' | 'individual'
  const [selectedOperator, setSelectedOperator] = useState(null);
  const [operators, setOperators] = useState([]);

  useEffect(() => {
    if (!isOversight) return;
    let alive = true;
    employeesApi.list({ role: 'operator' })
      .then((r) => {
        if (!alive) return;
        const list = (r.data || [])
          .filter((e) => (pick(e, 'role') || 'operator') === 'operator')
          .map((e) => ({ id: String(pick(e, 'id')), name: pick(e, 'full_name', 'name', 'username') || `Operator ${pick(e, 'id')}` }))
          .sort((a, b) => a.name.localeCompare(b.name));
        setOperators(list);
      })
      .catch(() => {});
    return () => { alive = false; };
  }, [isOversight]);

  // Default the operator picker when switching into Individual view.
  useEffect(() => {
    if (isOversight && view === 'individual' && !selectedOperator && operators.length) {
      setSelectedOperator(operators[0].id);
    }
  }, [isOversight, view, selectedOperator, operators]);

  // Whose workstation view is on screen? Operators always see their own; an
  // oversight user sees the picked operator in Individual view, or the board in All.
  const showingOperatorView = !isOversight || view === 'individual';
  const viewOperatorId = !isOversight ? selfId : (view === 'individual' ? selectedOperator : null);
  const viewOperatorName = isOversight ? (operators.find((o) => o.id === selectedOperator)?.name) : null;

  const { data, error, loading, refetch } = usePolling(
    () => (viewOperatorId == null
      ? Promise.resolve({ jobs: [], assigned: [] })
      : Promise.all([
        jobsApi.list({ assignedTo: viewOperatorId, operator: viewOperatorId }).then((r) => r.data).catch(() => []),
        // The shift-level workstation assignments (Work Assignment page) so a
        // staffed workstation shows a tab even before any job is queued there.
        workstationAssignmentsApi.mine(viewOperatorId).then((r) => r.data).catch(() => []),
      ]).then(([jobsData, assigned]) => ({ jobs: jobsData, assigned: assigned || [] }))),
    [viewOperatorId]
  );

  // Normalise to a flat job array regardless of envelope shape.
  const jobs = useMemo(() => {
    const jd = data && !Array.isArray(data) ? data.jobs : data;
    if (!jd) return [];
    if (Array.isArray(jd)) return jd;
    return jd.jobs || jd.items || jd.results || [];
  }, [data]);

  const assignedUnits = useMemo(() => (data && !Array.isArray(data) ? (data.assigned || []) : []), [data]);

  // Build the operator's workstation tabs from BOTH their shift assignments
  // (so a staffed workstation shows even with no jobs) and any workstation where
  // they have jobs. Keyed by workstation unit code.
  const stations = useMemo(() => {
    const map = new Map();
    for (const a of assignedUnits) {
      const code = pick(a, 'unit_code', 'workstation_type_code') || 'Unassigned';
      if (!map.has(code)) {
        map.set(code, {
          code,
          name: pick(a, 'name', 'unit_name', 'workstation_type_code') || code,
          unit_id: pick(a, 'workstation_unit_id', 'unit_id'),
          workstation_type_code: pick(a, 'workstation_type_code'),
          jobs: [],
        });
      }
    }
    for (const job of jobs) {
      const code = pick(job, 'workstation_code', 'unit_code', 'workstation', 'station', 'station_code') || 'Unassigned';
      const name = pick(job, 'workstation_name', 'unit_name', 'workstation_type_code') || code;
      if (!map.has(code)) map.set(code, { code, name, unit_id: pick(job, 'workstation_unit_id'), jobs: [] });
      map.get(code).jobs.push(job);
    }
    return Array.from(map.values()).sort((a, b) => a.code.localeCompare(b.code));
  }, [jobs, assignedUnits]);

  const [activeStation, setActiveStation] = useState(null);
  useEffect(() => {
    if (stations.length && (!activeStation || !stations.find((s) => s.code === activeStation))) {
      setActiveStation(stations[0].code);
    }
  }, [stations, activeStation]);

  const station = stations.find((s) => s.code === activeStation) || stations[0] || null;

  // SG-DLT bunch-grinding stations use a different model: the operator loads
  // several bars at once. Detect by the jobs' workstation type.
  const isBunch = (station?.jobs || []).some((j) => pick(j, 'workstation_type_code') === 'SG-DLT')
    || String(station?.workstation_type_code || station?.code || '').startsWith('SG-DLT');
  const unitId = pick(station?.jobs?.[0] || {}, 'workstation_unit_id') ?? station?.unit_id;

  // Within a station: the active (in-progress/paused) job vs. queued jobs.
  const activeJob = useMemo(
    () => (station ? station.jobs.find((j) => ACTIVE_STATUSES.includes(jobStatus(j))) : null),
    [station]
  );
  const queue = useMemo(
    () => (station ? station.jobs.filter((j) => !ACTIVE_STATUSES.includes(jobStatus(j))) : []),
    [station]
  );

  const [pending, setPending] = useState(null); // { id, action }
  const [pauseFor, setPauseFor] = useState(null); // job
  const [closeFor, setCloseFor] = useState(null); // job
  const [actionError, setActionError] = useState(null);
  const [showGen, setShowGen] = useState(false); // Generate-UID modal (TAG-01 operator)

  const runAction = useCallback(
    async (job, action, fn) => {
      setActionError(null);
      setPending({ id: jobId(job), action });
      try {
        await fn();
        await refetch();
      } catch (err) {
        setActionError(err?.message || 'Action failed — please try again.');
      } finally {
        setPending(null);
      }
    },
    [refetch]
  );

  const pendingFor = (job, action) => {
    if (!pending || pending.id !== jobId(job)) return null;
    return action ? (pending.action === action ? action : null) : pending.action;
  };

  const handleStart = (job) => runAction(job, 'start', () => jobsApi.start(jobId(job)));
  const handleResume = (job) => runAction(job, 'resume', () => jobsApi.resume(jobId(job)));
  const handleHold = (job) => {
    const reason = window.prompt('Reason for placing this job on hold:');
    if (!reason || !reason.trim()) return;
    return runAction(job, 'hold', () => jobsApi.hold(jobId(job), reason.trim()));
  };

  const handlePauseConfirm = (job) => (reason, notes) =>
    runAction(job, 'pause', () => jobsApi.pause(jobId(job), reason, notes)).then(() => setPauseFor(null));

  const handleCloseConfirm = (job) => async (payload) => {
    await runAction(job, 'close', async () => {
      await jobsApi.close(jobId(job), payload);
      // Advance the UID to its next step on successful close.
      const code = pick(job, 'uid', 'uid_code', 'code');
      if (code) {
        try {
          await uidsApi.advance(code, { from_step: jobStep(job) });
        } catch {
          // The close endpoint may already advance server-side; ignore a
          // duplicate-advance error rather than blocking the operator.
        }
      }
    });
    setCloseFor(null);
  };

  /* ── render states ── */

  // §1 — UIDs are minted only at the Tagging Table (TAG-01), the genesis of every
  // job. Band Saw Cutting (BSW-01) creates no UIDs — it just cuts the block into
  // plates. So the tag action is available only while the Tagging Table tab is the
  // active workstation, not whenever the operator merely has TAG-01 assigned.
  const activeIsTagging = !!station && /tag/i.test(`${station.code} ${station.name || ''}`);
  const canGenerateUid = showingOperatorView && canAct && activeIsTagging;

  const subtitle = !isOversight
    ? `${pick(user || {}, 'name', 'full_name', 'username') || 'Operator'} · your assigned workstations this shift${loading ? ' · loading…' : ''}`
    : view === 'individual'
      ? `Operator view — ${viewOperatorName || 'select an operator'}${loading && viewOperatorId ? ' · loading…' : ''}`
      : 'All working workstations · UIDs waiting and live operator jobs';

  const header = (
    <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 16, flexWrap: 'wrap' }}>
      <div>
        <div style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 24, letterSpacing: '-0.03em', color: T_PRIMARY }}>My Workstation</div>
        <div style={{ fontFamily: SANS, fontSize: 13, color: T_SECONDARY, marginTop: 4 }}>{subtitle}</div>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
        {isOversight && (
          <>
            <div style={{ display: 'inline-flex', border: '1px solid var(--border-input, #d6e0d2)', borderRadius: 'var(--radius-md, 9px)', overflow: 'hidden' }}>
              {[['all', 'All'], ['individual', 'Individual']].map(([key, label]) => {
                const on = view === key;
                return (
                  <button key={key} type="button" onClick={() => setView(key)}
                    style={{ padding: '7px 14px', border: 'none', cursor: 'pointer', fontFamily: MONO, fontSize: 11, letterSpacing: '0.04em', fontWeight: on ? 700 : 400,
                      background: on ? 'var(--ink-650, #15366a)' : 'transparent', color: on ? '#fff' : T_SECONDARY }}>
                    {label}
                  </button>
                );
              })}
            </div>
            {view === 'individual' && (
              <select className="form-select" style={{ height: 36, maxWidth: 220 }}
                value={selectedOperator || ''} onChange={(e) => setSelectedOperator(e.target.value || null)} disabled={operators.length === 0}>
                {operators.length === 0 && <option value="">No operators</option>}
                {operators.map((o) => <option key={o.id} value={o.id}>{o.name}</option>)}
              </select>
            )}
          </>
        )}
        {canGenerateUid && (
          <button className="btn btn-primary" type="button" onClick={() => setShowGen(true)} style={{ flexShrink: 0 }}>
            <Icon name="tag" size={15} /> Generate UID
          </button>
        )}
      </div>
    </div>
  );

  if (showingOperatorView && viewOperatorId && error) {
    return (
      <div style={{ padding: '28px 28px 60px', maxWidth: 1280 }}>
        {header}
        <div className="card" style={{ marginTop: 20, padding: 28, textAlign: 'center' }}>
          <div style={{ fontFamily: SANS, fontSize: 14, color: 'var(--status-danger-dark, #c0392b)' }}>
            {error.message || 'Could not load the queue.'}
          </div>
          <button className="btn btn-primary" style={{ marginTop: 14 }} onClick={refetch}>
            <Icon name="refresh" size={16} />Retry
          </button>
        </div>
      </div>
    );
  }

  if (showingOperatorView && viewOperatorId && loading && !data) {
    return (
      <div style={{ padding: '28px 28px 60px', maxWidth: 1280 }}>
        {header}
        <div className="card" style={{ marginTop: 20, padding: 40, textAlign: 'center', fontFamily: SANS, fontSize: 13, color: T_SECONDARY }}>
          Loading workstations…
        </div>
      </div>
    );
  }

  return (
    <div style={{ padding: '28px 28px 60px', maxWidth: 1280 }}>
      {header}

      {!showingOperatorView && <SwapSlotBanner />}

      {actionError && (
        <div className="card" style={{ marginTop: 16, padding: '12px 16px', display: 'flex', alignItems: 'center', gap: 10, borderLeft: '4px solid var(--status-danger, #e5484d)' }}>
          <Icon name="alert" size={18} color="#e5484d" />
          <span style={{ fontFamily: SANS, fontSize: 13, color: 'var(--status-danger-dark, #c0392b)', flex: 1 }}>{actionError}</span>
          <button className="btn btn-sm" onClick={() => setActionError(null)}>Dismiss</button>
        </div>
      )}

      {!showingOperatorView ? (
        <AllWorkstationsBoard />
      ) : (isOversight && view === 'individual' && !selectedOperator) ? (
        <div className="card" style={{ marginTop: 20, padding: 40, textAlign: 'center' }}>
          <Icon name="monitor" size={28} color={T_MUTED} />
          <div style={{ fontFamily: SANS, fontSize: 13, color: T_SECONDARY, marginTop: 10 }}>
            Pick an operator above to see their workstation view.
          </div>
        </div>
      ) : stations.length === 0 ? (
        <div className="card" style={{ marginTop: 20, padding: 40, textAlign: 'center' }}>
          <Icon name="monitor" size={28} color={T_MUTED} />
          <div style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 16, color: T_PRIMARY, marginTop: 10 }}>No workstations assigned</div>
          <div style={{ fontFamily: SANS, fontSize: 13, color: T_SECONDARY, marginTop: 4 }}>
            {isOversight
              ? `${viewOperatorName || 'This operator'} has no jobs allotted this shift.`
              : 'You have no jobs allotted to you this shift. Your supervisor assigns work here.'}
          </div>
        </div>
      ) : (
        <>
          {/* workstation tab strip */}
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 20 }}>
            {stations.map((s) => {
              const sActive = s.jobs.find((j) => ACTIVE_STATUSES.includes(jobStatus(j)));
              const sStatus = sActive ? jobStatus(sActive) : 'idle';
              const sel = s.code === activeStation;
              return (
                <button
                  key={s.code}
                  onClick={() => setActiveStation(s.code)}
                  className="btn"
                  style={{
                    height: 48,
                    padding: '0 18px',
                    background: sel ? 'var(--ink-650, #15366a)' : 'var(--bg-card, #fff)',
                    color: sel ? 'var(--text-onink, #eaf4e4)' : T_PRIMARY,
                    border: sel ? 'none' : '1px solid var(--border-input, #d6e0d2)',
                  }}
                >
                  <span style={{ width: 9, height: 9, borderRadius: '50%', background: dotColor(sStatus), display: 'inline-block' }} />
                  <span style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', lineHeight: 1.15 }}>
                    <span style={{ fontFamily: SANS, fontSize: 13, fontWeight: 700 }}>{s.name}</span>
                    {s.name !== s.code && <span style={{ fontFamily: MONO, fontSize: 10, opacity: 0.7 }}>{s.code}</span>}
                  </span>
                </button>
              );
            })}
          </div>

          {station && (
            <div style={{ marginTop: 18, display: 'flex', flexDirection: 'column', gap: 18 }}>
              {/* station heading */}
              <div>
                <div style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 18, letterSpacing: '-0.02em', color: T_PRIMARY }}>
                  {station.name}
                  {station.name !== station.code && <span style={{ fontFamily: MONO, fontWeight: 500, fontSize: 13, color: T_MUTED }}>{' '}· {station.code}</span>}
                  {isBunch && (
                    <span style={{ fontFamily: SANS, fontWeight: 500, fontSize: 14, color: T_SECONDARY }}>
                      {' '}— Bunch grinding
                    </span>
                  )}
                  {!isBunch && activeJob && (
                    <span style={{ fontFamily: SANS, fontWeight: 500, fontSize: 14, color: T_SECONDARY }}>
                      {' '}— {pick(activeJob, 'operation', 'operation_name', 'step_name') || 'Active job'}
                      {jobStep(activeJob) != null ? ` · Step ${jobStep(activeJob)}` : ''}
                    </span>
                  )}
                </div>
              </div>

              {isBunch ? (
                <BunchGrindingPanel unitId={unitId} nowMs={nowMs} canAct={canAct} />
              ) : (
                <>
                  {activeJob ? (
                    <ActiveJobCard
                      job={activeJob}
                      nowMs={nowMs}
                      canAct={canAct}
                      canHold={isSupervisor || isAdmin}
                      pendingAction={pendingFor(activeJob)}
                      onStart={() => handleStart(activeJob)}
                      onResume={() => handleResume(activeJob)}
                      onPause={() => setPauseFor(activeJob)}
                      onHold={() => handleHold(activeJob)}
                      onClose={() => setCloseFor(activeJob)}
                    />
                  ) : (
                    <div className="card" style={{ padding: 28, textAlign: 'center' }}>
                      <StatusPill status="idle" />
                      <div style={{ fontFamily: SANS, fontSize: 13, color: T_SECONDARY, marginTop: 10 }}>
                        No active job at this workstation. Start the next job from the queue below.
                      </div>
                    </div>
                  )}

                  {/* queue */}
                  <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
                    <div style={{ padding: '14px 18px', borderBottom: queue.length ? '1px solid var(--border-card, #e3ebde)' : 'none', display: 'flex', alignItems: 'center', gap: 8 }}>
                      <Icon name="list" size={16} color={T_SECONDARY} />
                      <span style={{ fontFamily: ARCHIVO, fontWeight: 800, fontSize: 14, letterSpacing: '-0.02em', color: T_PRIMARY }}>
                        Queue — {station.name}
                      </span>
                      <Mono style={{ fontSize: 11, color: T_MUTED }}>
                        ({queue.length} {queue.length === 1 ? 'UID' : 'UIDs'} waiting)
                      </Mono>
                    </div>
                    {queue.length === 0 ? (
                      <div style={{ padding: '20px 18px', fontFamily: SANS, fontSize: 13, color: T_SECONDARY }}>
                        Queue is clear — no UIDs waiting at this workstation.
                      </div>
                    ) : (
                      queue.map((job, i) => (
                        <QueueRow
                          key={jobId(job) ?? i}
                          job={job}
                          idx={i}
                          nowMs={nowMs}
                          canAct={canAct && !activeJob}
                          pending={pendingFor(job, 'start')}
                          onStart={() => handleStart(job)}
                        />
                      ))
                    )}
                  </div>
                </>
              )}
            </div>
          )}
        </>
      )}

      {pauseFor && (
        <PauseModal
          job={pauseFor}
          busy={pendingFor(pauseFor, 'pause') === 'pause'}
          onCancel={() => setPauseFor(null)}
          onConfirm={handlePauseConfirm(pauseFor)}
        />
      )}
      {closeFor && (
        <CloseModal
          job={closeFor}
          timers={computeTimers(closeFor, nowMs)}
          busy={pendingFor(closeFor, 'close') === 'close'}
          onCancel={() => setCloseFor(null)}
          onConfirm={handleCloseConfirm(closeFor)}
        />
      )}
      {showGen && (
        <GenerateUidModal
          onClose={() => setShowGen(false)}
          onDone={refetch}
        />
      )}
    </div>
  );
}
